/**
 * Generate `deploy/security-headers.caddy` from `apps/web/security-headers.ts`.
 * Run with `pnpm gen:caddy-headers`.
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { CADDY_SECURITY_HEADERS } from "../security-headers.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "../../..");
const out = join(root, "deploy/security-headers.caddy");

const lines = [
  "# Generated by `pnpm gen:caddy-headers` from apps/web/security-headers.ts.",
  "# Do not edit by hand.",
  "",
  "header {",
];
for (const [name, value] of Object.entries(CADDY_SECURITY_HEADERS)) {
  const quoted =
    value.includes(" ") || value.includes("'") || value.includes(";") ? `"${value}"` : value;
  lines.push(`	${name} ${quoted}`);
}
lines.push("	-Server");
lines.push("}");
lines.push("");

writeFileSync(out, lines.join("\n"));
process.stdout.write(`wrote ${out}\n`);
